/* ===================== BÀI 44 · 8251 USART và truyền nối tiếp ===================== */
/* Bài 44 · 8251 USART và truyền nối tiếp (AMTS-EMB-002-M11-L04, X86-044) — sinh bởi tools/author/mpu8086/l44.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8086 và bài tập chấm tự động (đề, code mẫu, test). Lời giải không nằm ở đây. */
const P44=[{"label": "Ví dụ: gửi OK, hỏi vòng TxRDY", "code": "; Ví dụ 1: gửi chữ OK qua 8251A (hỏi vòng TxRDY)\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        MOV     AL, 96H                 ; 8254 bộ đếm 2: chỉ LSB, mode 3\n        OUT     8EH, AL\n        MOV     AL, 16                  ; TxC = RxC = 2,5 MHz / 16\n        OUT     8CH, AL\n        MOV     AL, 4EH                 ; từ chế độ: x16, 8N1 (8 bit, 1 stop)\n        OUT     9AH, AL\n        MOV     AL, 15H                 ; từ lệnh: TxEN, RxE, xóa cờ lỗi\n        OUT     9AH, AL\n        MOV     AL, 'O'\n        OUT     98H, AL                 ; ghi vào bộ đệm phát\ncho1:\n        IN      AL, 9AH                 ; trạng thái\n        TEST    AL, 01H                 ; TxRDY?\n        JZ      cho1\n        MOV     AL, 'K'\n        OUT     98H, AL                 ; ghi vào bộ đệm phát\ncho2:\n        IN      AL, 9AH                 ; trạng thái\n        TEST    AL, 01H                 ; TxRDY?\n        JZ      cho2\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Khởi tạo: 8254 bộ đếm 2 (96h, N = 16) tạo TxC 156,25 kHz; 8251A từ chế độ 4Eh, từ lệnh 15h. Mỗi ký tự: ghi 98h rồi hỏi vòng trạng thái tới khi TxRDY = 1. Terminal 9600 baud nhận “OK” dù 8251A chạy 9765,6 baud (lệch 1,7 %). Đoán trước: đọc 9Ah ngay sau khi ghi chữ O, bit TxRDY bằng mấy? Đáp án 0 (bộ đệm còn chữ O)."}, {"label": "Ví dụ: nhận chữ thường, gửi lại chữ hoa", "code": "; Ví dụ 2: nhận một chữ thường, gửi lại chữ hoa\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nkyTu    DB      ?                       ; byte nhận được\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AL, 96H                 ; 8254 bộ đếm 2: chỉ LSB, mode 3\n        OUT     8EH, AL\n        MOV     AL, 16                  ; TxC = RxC = 2,5 MHz / 16\n        OUT     8CH, AL\n        MOV     AL, 4EH                 ; từ chế độ: x16, 8N1 (8 bit, 1 stop)\n        OUT     9AH, AL\n        MOV     AL, 15H                 ; từ lệnh: TxEN, RxE, xóa cờ lỗi\n        OUT     9AH, AL\nthu:\n        IN      AL, 9AH\n        TEST    AL, 02H                 ; RxRDY?\n        JZ      thu\n        IN      AL, 98H                 ; đọc byte, RxRDY về 0\n        MOV     kyTu, AL\n        SUB     AL, 20H                 ; chữ thường → chữ hoa\n        MOV     AH, AL\nphat:\n        IN      AL, 9AH\n        TEST    AL, 01H                 ; chờ TxRDY = 1\n        JZ      phat\n        MOV     AL, AH\n        OUT     98H, AL\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Terminal gửi chữ q. Chương trình chờ RxRDY (bit 1), đọc 98h được 71h, trừ 20h thành 51h (Q), giữ trong AH, chờ TxRDY rồi gửi lại: terminal nhận Q. Đoán trước: sau SUB AL, 20h, AL bằng bao nhiêu (hệ 16)? Đáp án 51h."}, {"label": "Lỗi: không chờ TxRDY, mất ký tự", "code": "; Lỗi: ghi liên tiếp, không chờ TxRDY\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        MOV     AL, 96H                 ; 8254 bộ đếm 2: chỉ LSB, mode 3\n        OUT     8EH, AL\n        MOV     AL, 16                  ; TxC = RxC = 2,5 MHz / 16\n        OUT     8CH, AL\n        MOV     AL, 4EH                 ; từ chế độ: x16, 8N1 (8 bit, 1 stop)\n        OUT     9AH, AL\n        MOV     AL, 15H                 ; từ lệnh: TxEN, RxE, xóa cờ lỗi\n        OUT     9AH, AL\n        MOV     AL, 'A'\n        OUT     98H, AL\n        MOV     AL, 'B'\n        OUT     98H, AL                 ; bộ đệm còn đầy?\n        MOV     AL, 'C'\n        OUT     98H, AL\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Lỗi cố ý: ghi A, B, C liên tiếp không chờ TxRDY. A kịp chuyển vào thanh ghi dịch ở một cạnh TxC trước khi B được ghi; B nằm trong bộ đệm thì bị C ghi đè (giữa hai lần ghi chưa có cạnh TxC nào). Terminal nhận “AC”; phần Bo I/O cảnh báo. Kết quả cụ thể phụ thuộc vị trí cạnh TxC: không bao giờ dựa vào may rủi này. Sửa: chờ TxRDY trước mỗi lần ghi (Ví dụ 1)."}, {"label": "Lỗi: sai baud (N = 8), terminal nhận rác", "code": "; Lỗi: sai baud, N = 8 cho 19 531 baud\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        MOV     AL, 96H                 ; 8254 bộ đếm 2: chỉ LSB, mode 3\n        OUT     8EH, AL\n        MOV     AL, 8                   ; SAI: terminal chạy 9600 baud\n        OUT     8CH, AL\n        MOV     AL, 4EH                 ; từ chế độ: x16, 8N1 (8 bit, 1 stop)\n        OUT     9AH, AL\n        MOV     AL, 15H                 ; từ lệnh: TxEN, RxE, xóa cờ lỗi\n        OUT     9AH, AL\n        MOV     AL, 'O'\n        OUT     98H, AL                 ; ghi vào bộ đệm phát\ncho1:\n        IN      AL, 9AH                 ; trạng thái\n        TEST    AL, 01H                 ; TxRDY?\n        JZ      cho1\n        MOV     AL, 'K'\n        OUT     98H, AL                 ; ghi vào bộ đệm phát\ncho2:\n        IN      AL, 9AH                 ; trạng thái\n        TEST    AL, 01H                 ; TxRDY?\n        JZ      cho2\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Lỗi cố ý: N = 8 nên 8251A chạy 19 531 baud (gấp đôi). Terminal 9600 baud lấy mẫu sai chỗ: hai khung O, K bị đọc thành một byte rác 9Dh (hiện ·). Sửa: N = 16. Đoán trước: terminal nhận được mấy ký tự? Đáp án 1 (rác)."}, {"label": "Bẫy: ghi từ chế độ hai lần", "code": "; Bẫy: ghi từ chế độ hai lần\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        MOV     AL, 96H                 ; 8254 bộ đếm 2: chỉ LSB, mode 3\n        OUT     8EH, AL\n        MOV     AL, 16                  ; TxC = RxC = 2,5 MHz / 16\n        OUT     8CH, AL\n        MOV     AL, 4EH                 ; từ chế độ\n        OUT     9AH, AL\n        MOV     AL, 4EH                 ; tưởng ghi lại từ chế độ\n        OUT     9AH, AL                 ; thật ra là từ lệnh, bit IR = 1\n        MOV     AL, 15H\n        OUT     9AH, AL                 ; bị hiểu là từ chế độ\n        MOV     AL, 'O'\n        OUT     98H, AL\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Bẫy: ghi 4Eh lần hai. Lần này 4Eh là từ lệnh có IR = 1 (D6) → reset trong; byte 15h sau đó bị hiểu là từ chế độ (×1, 6 bit, có parity, số bit stop không hợp lệ). Không có từ lệnh TxEN nên chữ O nằm trong bộ đệm, không ra dây: terminal không nhận gì. Sửa: chỉ ghi từ chế độ một lần, hoặc khởi tạo an toàn (Ví dụ 7)."}, {"label": "Ví dụ: đọc chậm, cờ tràn OE", "code": "; Ví dụ 6: đọc chậm, cờ tràn OE bật\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\ntrangThai DB    ?\nkyTu    DB      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AL, 96H                 ; 8254 bộ đếm 2: chỉ LSB, mode 3\n        OUT     8EH, AL\n        MOV     AL, 16                  ; TxC = RxC = 2,5 MHz / 16\n        OUT     8CH, AL\n        MOV     AL, 4EH                 ; từ chế độ: x16, 8N1 (8 bit, 1 stop)\n        OUT     9AH, AL\n        MOV     AL, 15H                 ; từ lệnh: TxEN, RxE, xóa cờ lỗi\n        OUT     9AH, AL\n        MOV     CX, 1000                ; bận việc khác khoảng 3,4 ms\ncho:\n        LOOP    cho\n        IN      AL, 9AH\n        MOV     trangThai, AL\n        IN      AL, 98H\n        MOV     kyTu, AL\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Terminal gửi A rồi B trong khi chương trình bận (LOOP 1000 lần ≈ 3,4 ms). B tới khi A chưa được đọc: B đè A, OE = 1. Trạng thái 17h = TxRDY, RxRDY, TxEMPTY, OE; đọc 98h được 42h (B). Đoán trước: bit OE (bit 4) bằng mấy? Đáp án 1."}, {"label": "Ví dụ: khởi tạo an toàn (00h × 3, 40h)", "code": "; Ví dụ 7: khởi tạo 8251A an toàn rồi gửi U\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        MOV     AL, 96H                 ; 8254 bộ đếm 2: chỉ LSB, mode 3\n        OUT     8EH, AL\n        MOV     AL, 16                  ; TxC = RxC = 2,5 MHz / 16\n        OUT     8CH, AL\n        MOV     AL, 00H                 ; ba byte 00h: chip về chỗ chờ từ lệnh\n        OUT     9AH, AL\n        OUT     9AH, AL\n        OUT     9AH, AL\n        MOV     AL, 40H                 ; từ lệnh: IR = 1, reset trong\n        OUT     9AH, AL\n        MOV     AL, 4EH                 ; từ chế độ: x16, 8N1 (8 bit, 1 stop)\n        OUT     9AH, AL\n        MOV     AL, 15H                 ; từ lệnh: TxEN, RxE, xóa cờ lỗi\n        OUT     9AH, AL\n        MOV     AL, 'U'\n        OUT     98H, AL                 ; ghi vào bộ đệm phát\ncho1:\n        IN      AL, 9AH                 ; trạng thái\n        TEST    AL, 01H                 ; TxRDY?\n        JZ      cho1\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Khởi tạo an toàn: 00h, 00h, 00h rồi 40h (IR) đưa 8251A về chờ từ chế độ dù trước đó nó đang ở trạng thái nào; sau đó 4Eh, 15h như thường. Terminal nhận U. Đoán trước: với chip vừa reset, byte 00h đầu tiên được hiểu là gì? Đáp án từ chế độ (đồng bộ), hai byte 00h sau là ký tự đồng bộ."}];
const sim44=makeX86Sim(document.getElementById("x86-l44"),{id:"s44",presets:P44,file:"BAI44.ASM"});
const EX44=[{"t": "Gửi một dòng qua 8251A", "d": "Code mẫu đã khởi tạo 8254 (bộ đếm 2, N = 16 → 9765,6 baud với ×16) và 8251A (4Eh, 15h), rồi đọc một dòng từ bàn phím bằng INT 21h hàm 0Ah vào buf (byte 1 là số ký tự, ký tự từ byte 2). Gửi lần lượt từng ký tự của dòng qua 8251A (cổng dữ liệu 98h), trước mỗi lần ghi phải chờ bit TxRDY (bit 0 của 9Ah) bằng 1. Không gửi ký tự Enter. Trang chấm chữ mà terminal 9600 baud nhận được.", "start": "; Bài tập 1: gửi một dòng gõ từ bàn phím qua 8251A\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nbuf     DB      20, ?, 20 DUP(?)        ; tối đa, số đã đọc, ký tự\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AL, 96H                 ; 8254 bộ đếm 2: chỉ LSB, mode 3\n        OUT     8EH, AL\n        MOV     AL, 16                  ; TxC = RxC = 2,5 MHz / 16\n        OUT     8CH, AL\n        MOV     AL, 4EH                 ; từ chế độ: x16, 8N1 (8 bit, 1 stop)\n        OUT     9AH, AL\n        MOV     AL, 15H                 ; từ lệnh: TxEN, RxE, xóa cờ lỗi\n        OUT     9AH, AL\n        MOV     DX, OFFSET buf          ; đọc một dòng (INT 21h/0Ah)\n        MOV     AH, 0AH\n        INT     21H\n; TODO: gửi buf[1] ký tự từ buf+2, mỗi ký tự chờ TxRDY\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"in": "HELLO", "io": {"run": 40000, "want": {"term": "HELLO"}}}, {"in": "8086", "io": {"run": 40000, "want": {"term": "8086"}}}, {"in": "A", "io": {"run": 40000, "want": {"term": "A"}}}, {"in": "AMTS 2026", "io": {"run": 40000, "want": {"term": "AMTS 2026"}}}, {"in": "xyz!", "io": {"run": 40000, "want": {"term": "xyz!"}}}, {"in": "Hi there", "io": {"run": 40000, "want": {"term": "Hi there"}}}]}, {"t": "Echo chữ hoa tới dấu chấm", "d": "Terminal gửi một dòng kết thúc bằng dấu chấm. Lặp: chờ RxRDY (bit 1 của 9Ah), đọc byte ở 98h; nếu là chữ thường a–z thì đổi thành chữ hoa, ký tự khác giữ nguyên; chờ TxRDY rồi gửi lại. Gặp dấu chấm thì gửi dấu chấm rồi kết thúc. Biến soKyTu đếm số ký tự trước dấu chấm. Trang chấm chữ terminal nhận lại và soKyTu.", "start": "; Bài tập 2: echo chữ hoa tới dấu chấm\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nsoKyTu  DB      0                       ; số ký tự trước dấu chấm\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AL, 96H                 ; 8254 bộ đếm 2: chỉ LSB, mode 3\n        OUT     8EH, AL\n        MOV     AL, 16                  ; TxC = RxC = 2,5 MHz / 16\n        OUT     8CH, AL\n        MOV     AL, 4EH                 ; từ chế độ: x16, 8N1 (8 bit, 1 stop)\n        OUT     9AH, AL\n        MOV     AL, 15H                 ; từ lệnh: TxEN, RxE, xóa cờ lỗi\n        OUT     9AH, AL\n; TODO: lặp: chờ RxRDY, đọc; a-z thành A-Z;\n;       chờ TxRDY, gửi; gặp '.' thì gửi rồi dừng\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"io": {"term": {"send": "abc."}, "run": 20000, "want": {"term": "ABC."}}, "mem": [{"at": "soKyTu", "bytes": [3]}]}, {"io": {"term": {"send": "Hello."}, "run": 20000, "want": {"term": "HELLO."}}, "mem": [{"at": "soKyTu", "bytes": [5]}]}, {"io": {"term": {"send": "."}, "run": 20000, "want": {"term": "."}}, "mem": [{"at": "soKyTu", "bytes": [0]}]}, {"io": {"term": {"send": "x1y2."}, "run": 20000, "want": {"term": "X1Y2."}}, "mem": [{"at": "soKyTu", "bytes": [4]}]}, {"io": {"term": {"send": "AMTS."}, "run": 20000, "want": {"term": "AMTS."}}, "mem": [{"at": "soKyTu", "bytes": [4]}]}, {"io": {"term": {"send": "go go."}, "run": 20000, "want": {"term": "GO GO."}}, "mem": [{"at": "soKyTu", "bytes": [5]}]}]}, {"t": "Baud theo công tắc, mã ngắn", "d": "Công tắc PB (0–4) chọn baud 1200, 2400, 4800, 9600, 19200. Với ×16 và CLK 2,5 MHz, số đếm cho bộ đếm 2 là N = 2 500 000 / (16 × baud) làm tròn: 130, 65, 33, 16, 8. Nạp N cho bộ đếm 2 (mode 3), khởi tạo 8251A (4Eh, 15h) rồi gửi chữ U; terminal chạy đúng baud đã chọn phải nhận được U. Code mẫu đúng nhưng so sánh lần lượt nên dài; viết lại để mã không quá giới hạn byte. Giữ 8255A ở 8Bh (B, C vào).", "start": "; Bài tập 3: chọn baud theo công tắc, mã ngắn\n; Bản này đúng nhưng dài: so sánh lần lượt từng giá trị.\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        MOV     AL, 8BH                 ; 8255A: B, C vào\n        OUT     86H, AL\n        IN      AL, 82H                 ; 0-4: 1200, 2400, 4800, 9600, 19200\n        CMP     AL, 0\n        JNE     b1\n        MOV     AH, 130\n        JMP     dat\nb1:\n        CMP     AL, 1\n        JNE     b2\n        MOV     AH, 65\n        JMP     dat\nb2:\n        CMP     AL, 2\n        JNE     b3\n        MOV     AH, 33\n        JMP     dat\nb3:\n        CMP     AL, 3\n        JNE     b4\n        MOV     AH, 16\n        JMP     dat\nb4:\n        MOV     AH, 8\ndat:\n        MOV     AL, 96H                 ; bộ đếm 2: chỉ LSB, mode 3\n        OUT     8EH, AL\n        MOV     AL, AH\n        OUT     8CH, AL\n        MOV     AL, 4EH                 ; từ chế độ: x16, 8N1 (8 bit, 1 stop)\n        OUT     9AH, AL\n        MOV     AL, 15H                 ; từ lệnh: TxEN, RxE, xóa cờ lỗi\n        OUT     9AH, AL\n        MOV     AL, 'U'\n        OUT     98H, AL\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"io": {"sw": 3, "term": {"baud": 9600}, "run": 60000, "want": {"term": "U", "pit": {"2": {"mode": 3, "count": 16}}}}}, {"io": {"sw": 0, "term": {"baud": 1200}, "run": 60000, "want": {"term": "U", "pit": {"2": {"mode": 3, "count": 130}}}}}, {"io": {"sw": 1, "term": {"baud": 2400}, "run": 60000, "want": {"term": "U", "pit": {"2": {"mode": 3, "count": 65}}}}}, {"io": {"sw": 2, "term": {"baud": 4800}, "run": 60000, "want": {"term": "U", "pit": {"2": {"mode": 3, "count": 33}}}}}, {"io": {"sw": 4, "term": {"baud": 19200}, "run": 60000, "want": {"term": "U", "pit": {"2": {"mode": 3, "count": 8}}}}}, {"io": {"sw": 3, "term": {"baud": 9600}, "run": 60000, "want": {"term": "U", "pit": {"2": {"mode": 3, "count": 16}}}}}], "perf": {"bytes": 45}}];
