makeQuiz("quiz44","score44",[{"q": "Ở 4800 baud, khung 8N1. Một khung dài bao lâu và tối đa bao nhiêu ký tự mỗi giây?", "o": ["≈ 1,67 ms; 600 ký tự/s", "≈ 0,21 ms; 4800 ký tự/s", "≈ 2,08 ms; 4800 ký tự/s", "≈ 2,08 ms; 480 ký tự/s"], "a": 3, "e": "8N1 = 1 start + 8 dữ liệu + 1 stop = 10 bit. 10 / 4800 s ≈ 2,08 ms; 4800 / 10 = 480 ký tự mỗi giây. 1,67 ms là khung 8 bit (quên start, stop)."}, {"q": "8254 có CLK 2,5 MHz, 8251A dùng hệ số ×16. Cần 2400 baud. N của bộ đếm 2 và sai số baud?", "o": ["N = 1042, đúng 2400 baud", "N = 65, ≈ 2403,8 baud, sai số ≈ +0,16 %", "N = 130, ≈ 1201,9 baud", "N = 65, đúng 2400 baud"], "a": 1, "e": "N = 2 500 000 / (16 × 2400) = 65,1 → 65; baud thật = 2 500 000 / (65 × 16) ≈ 2403,8, lệch +0,16 %. N = 130 là cho 1200 baud."}, {"q": "Từ chế độ 4Eh (×16, 8 bit, không parity, 1 stop) đã ghi. Chương trình ghi tiếp 4Eh vào 9Ah “cho chắc”. Điều gì xảy ra?", "o": ["Không sao, 8251A ghi đè từ chế độ bằng cùng giá trị", "8251A báo lỗi khung FE", "Byte thứ hai là từ lệnh có IR = 1: 8251A reset trong và chờ từ chế độ mới", "8251A chuyển sang chế độ đồng bộ"], "a": 2, "e": "Sau từ chế độ, mọi byte ghi vào cổng điều khiển là từ lệnh. 4Eh = 0100 1110b có D6 (IR) = 1 nên chip reset trong; byte kế tiếp sẽ bị hiểu là từ chế độ (Ví dụ 5)."}, {"q": "Đọc 9Ah được 17h. Phát biểu nào đúng?", "o": ["Bộ phát đang bận, chưa được ghi byte mới", "Có lỗi parity ở byte vừa nhận", "8251A chưa được khởi tạo", "Có byte chờ đọc và đã có byte bị mất vì tràn (OE = 1)"], "a": 3, "e": "17h = 0001 0111b: D0 TxRDY = 1, D1 RxRDY = 1, D2 TxEMPTY = 1, D4 OE = 1. PE (D3) và FE (D5) bằng 0 (Ví dụ 6)."}, {"q": "Nối TxD của 8251A (mức TTL) thẳng vào chân RxD của cổng RS-232 trên máy tính cũ. Vì sao không làm vậy?", "o": ["Vì 8251A chỉ chạy được ở chế độ đồng bộ với RS-232", "Vì RS-232 cần 16 dây dữ liệu song song", "RS-232 dùng mức điện áp âm/dương và đảo mức so với TTL; cần chip chuyển mức như MAX232", "Không sao, RS-232 dùng đúng mức 0 V và 5 V"], "a": 2, "e": "Mức của RS-232 khác TTL (mark là điện áp âm) nên phải qua bộ chuyển mức (MAX232, 1488/1489) hoặc dùng bộ chuyển USB–UART mức TTL."}]);

